{{ config(materialized='table') }}

with
golden_gp_hub as (
    select
        gp_hk,
        gp_business_key,
        load_datetime,
        record_source
    from {{ ref("investment__gp_vault__hub_gp") }}
),
golden_gp_gp_detail_ranked as (
    select
        gp_hk,
        gp_name,
        gp_domicile,
        gp_relationship_start_on,
        gp_lei,
        effective_from,
        row_number() over (partition by gp_hk order by hashdiff_basis_version desc, effective_from desc) as dpf_version_rank
    from {{ ref("investment__gp_vault__sat_gp_detail") }}
),
golden_gp_gp_detail_current as (
    select
        gp_hk,
        gp_name,
        gp_domicile,
        gp_relationship_start_on,
        gp_lei,
        effective_from
    from golden_gp_gp_detail_ranked
    where dpf_version_rank = 1
),
golden_gp_gp_name_candidates as (
    select
        gp_hk,
        gp_name as dpf_value,
        effective_from,
        1 as dpf_source_priority
    from golden_gp_gp_detail_current
    where gp_name is not null
),
golden_gp_gp_name_ranked as (
    select
        gp_hk,
        dpf_value,
        row_number() over (partition by gp_hk order by effective_from desc, dpf_source_priority asc) as dpf_version_rank
    from golden_gp_gp_name_candidates
),
golden_gp_gp_name as (
    select
        gp_hk,
        dpf_value
    from golden_gp_gp_name_ranked
    where dpf_version_rank = 1
),
golden_gp_gp_domicile_candidates as (
