    from golden_gp_gp_relationship_start_on_candidates
),
golden_gp_gp_relationship_start_on as (
    select
        gp_hk,
        dpf_value
    from golden_gp_gp_relationship_start_on_ranked
    where dpf_version_rank = 1
),
golden_gp_gp_lei_candidates as (
    select
        gp_hk,
        gp_lei as dpf_value,
