        1 as dpf_source_priority
    from golden_gp_gp_detail_current
    where gp_lei is not null
),
golden_gp_gp_lei_ranked as (
    select
        gp_hk,
        dpf_value,
        row_number() over (partition by gp_hk order by dpf_source_priority asc, effective_from desc) as dpf_version_rank
    from golden_gp_gp_lei_candidates
),
golden_gp_gp_lei as (
    select
        gp_hk,
        dpf_value
    from golden_gp_gp_lei_ranked
    where dpf_version_rank = 1
),
golden_gp_joined as (
    select
        golden_gp_hub.gp_hk as gp_hk,
        golden_gp_hub.gp_business_key as gp_business_key,
        golden_gp_gp_name.dpf_value as gp_name,
        golden_gp_gp_domicile.dpf_value as gp_domicile,
        golden_gp_gp_relationship_start_on.dpf_value as gp_relationship_start_on,
        golden_gp_gp_lei.dpf_value as gp_lei,
        golden_gp_hub.load_datetime as load_datetime,
        golden_gp_hub.record_source as record_source
    from golden_gp_hub
    left join golden_gp_gp_name
        on golden_gp_gp_name.gp_hk = golden_gp_hub.gp_hk
    left join golden_gp_gp_domicile
        on golden_gp_gp_domicile.gp_hk = golden_gp_hub.gp_hk
    left join golden_gp_gp_relationship_start_on
        on golden_gp_gp_relationship_start_on.gp_hk = golden_gp_hub.gp_hk
    left join golden_gp_gp_lei
        on golden_gp_gp_lei.gp_hk = golden_gp_hub.gp_hk
)

select
    cast(gp_hk as {{ dpf_type('string') }}) as gp_hk,
    cast(gp_business_key as {{ dpf_type('string') }}) as gp_business_key,
    cast(gp_name as {{ dpf_type('string') }}) as gp_name,
